const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { Worker, isMainThread, parentPort, workerData } = require('worker_threads');

const UPLOAD_DIR = '/var/uploads';
const PROCESSING_DIR = '/var/processing';
const QUARANTINE_DIR = '/var/quarantine';
const SAFE_DIR = '/var/safe';

class FileValidator {
  constructor() {
    this.allowedMimeTypes = new Set(['image/png', 'image/jpeg', 'application/pdf']);
    this.maxFileSize = 10 * 1024 * 1024; // 10MB
  }

  getMimeFromBuffer(buffer) {
    if (buffer[0] === 0x89 && buffer[1] === 0x50) return 'image/png';
    if (buffer[0] === 0xFF && buffer[1] === 0xD8) return 'image/jpeg';
    if (buffer[0] === 0x25 && buffer[1] === 0x50) return 'application/pdf';
    return 'application/octet-stream';
  }

  validateBuffer(buffer) {
    if (buffer.length > this.maxFileSize) {
      return { valid: false, reason: 'File too large' };
    }
    const mime = this.getMimeFromBuffer(buffer);
    if (!this.allowedMimeTypes.has(mime)) {
      return { valid: false, reason: `Disallowed type: ${mime}` };
    }
    return { valid: true, mime };
  }
}

class JobLock {
  constructor() {
    this.locks = new Map();
  }

  async acquire(jobId) {
    const lockFile = path.join(PROCESSING_DIR, `${jobId}.lock`);
    try {
      await fs.promises.writeFile(lockFile, process.pid.toString(), { flag: 'wx' });
      this.locks.set(jobId, lockFile);
      return true;
    } catch (e) {
      if (e.code === 'EEXIST') return false;
      throw e;
    }
  }

  async release(jobId) {
    const lockFile = this.locks.get(jobId);
    if (lockFile) {
      await fs.promises.unlink(lockFile).catch(() => {});
      this.locks.delete(jobId);
    }
  }
}

class UploadWorker {
  constructor() {
    this.validator = new FileValidator();
    this.jobLock = new JobLock();
    this.processingJobs = new Map();
  }

  generateSafeName(originalName) {
    const ext = path.extname(originalName).toLowerCase();
    const allowedExts = ['.png', '.jpg', '.jpeg', '.pdf'];
    const safeExt = allowedExts.includes(ext) ? ext : '';
    const hash = crypto.randomBytes(16).toString('hex');
    return `${hash}${safeExt}`;
  }

  async atomicCopyToProcessing(jobId, uploadPath) {
    const safeName = this.generateSafeName(path.basename(uploadPath));
    const processingPath = path.join(PROCESSING_DIR, safeName);
    // Read content into memory atomically - no TOCTOU possible after this point
    const content = await fs.promises.readFile(uploadPath);
    this.processingJobs.set(jobId, { content, safeName });
    return content;
  }

  async processJob(job) {
    const { jobId, uploadPath, userId } = job;

    const resolvedUpload = path.resolve(uploadPath);
    // Enforce directory boundary to prevent prefix-match bypass (e.g. /var/uploads-evil)
    if (resolvedUpload !== UPLOAD_DIR &&
        !resolvedUpload.startsWith(UPLOAD_DIR + path.sep)) {
      throw new Error('Invalid upload path');
    }

    // Verify it's a regular file, not a symlink
    const lstats = await fs.promises.lstat(resolvedUpload);
    if (!lstats.isFile()) {
      throw new Error('Upload must be a regular file');
    }

    const acquired = await this.jobLock.acquire(jobId);
    if (!acquired) {
      console.log(`Job ${jobId} already being processed`);
      return { status: 'skipped', reason: 'already_processing' };
    }

    try {
      // Read file content into memory once - all subsequent operations use this buffer
      const content = await this.atomicCopyToProcessing(jobId, resolvedUpload);

      // Validate the buffer content (no filesystem re-reads)
      const validation = this.validator.validateBuffer(content);

      if (!validation.valid) {
        await this.quarantineContent(content, jobId);
        return { status: 'rejected', reason: validation.reason };
      }

      // Write validated content directly to final destination
      const finalPath = await this.finalizeFile(jobId, content, userId);
      return { status: 'completed', path: finalPath };
    } finally {
      await this.jobLock.release(jobId);
    }
  }

  async finalizeFile(jobId, content, userId) {
    const jobInfo = this.processingJobs.get(jobId);
    const sanitizedUserId = userId.replace(/[^a-zA-Z0-9_-]/g, '');
    if (!sanitizedUserId) {
      throw new Error('Invalid user ID');
    }
    const userDir = path.join(SAFE_DIR, sanitizedUserId);
    await fs.promises.mkdir(userDir, { recursive: true });

    const destPath = path.join(userDir, jobInfo.safeName);
    // Write the already-validated buffer directly - no re-read from filesystem
    await fs.promises.writeFile(destPath, content, { mode: 0o644 });
    this.processingJobs.delete(jobId);
    return destPath;
  }

  async quarantineContent(content, jobId) {
    const quarantineName = `${jobId}_${crypto.randomBytes(8).toString('hex')}`;
    const quarantinePath = path.join(QUARANTINE_DIR, quarantineName);
    await fs.promises.writeFile(quarantinePath, content, { mode: 0o600 });
    this.processingJobs.delete(jobId);
  }
}

// Worker thread message handler
if (!isMainThread) {
  const worker = new UploadWorker();
  parentPort.on('message', async (job) => {
    try {
      const result = await worker.processJob(job);
      parentPort.postMessage({ jobId: job.jobId, ...result });
    } catch (err) {
      parentPort.postMessage({ jobId: job.jobId, status: 'error', error: err.message });
    }
  });
}

module.exports = { UploadWorker, FileValidator, JobLock };
